def _local_native_path(self, path: str) -> Optional[str]:
    """Translate only paths proven to name this local host's namespace.

    MSYS drive mounts are unambiguous; /tmp, /etc, /dev and drive-relative
    Windows paths are not. Those keep their existing shell semantics.
    Never resolve a remote backend's paths on the controller.
    """
    if not self._lsp_local_only():
        return None
    from tools.environments.local import _IS_WINDOWS, _msys_to_windows_path
    if not _IS_WINDOWS:
        return path
    import ntpath
    mapped = _msys_to_windows_path(path)
    drive, tail = ntpath.splitdrive(mapped)
    if drive:
        if not tail.startswith(('\\', '/')):
            return None
        if drive.startswith(('\\\\?', '\\\\.')):
            return None
        return mapped
    if mapped.startswith(('\\', '/')):
        return None
    cwd = _msys_to_windows_path(getattr(self.env, 'cwd', None) or self.cwd)
    cwd_drive, cwd_tail = ntpath.splitdrive(cwd)
    if not cwd_drive or not cwd_tail.startswith(('\\', '/')):
        return None
    return ntpath.join(cwd, mapped)

def _native_read_enabled(self) -> bool:
    """Local bounded reads; unsupported path namespaces stay on the shell."""
    flag = os.environ.get("HERMES_NATIVE_FILE_READ", "1").strip().lower()
    if flag in ("0", "false", "no", "off"):
        return False
    from tools.toolrush_runtime import enabled
    return self._lsp_local_only() and enabled('fast_read', 'TOOLRUSH_FASTLANE')

